from appium.webdriver.common.appiumby import AppiumBy
state = {'package': driver.current_package, 'activity': driver.current_activity}
els = driver.find_elements(AppiumBy.XPATH, '//*')
facts=[]
for e in els:
    try:
        d={k:e.get_attribute(k) for k in ('className','resource-id','text','content-desc','clickable','bounds')}
        if d['text'] or d['content-desc'] or d['clickable']=='true': facts.append(d)
    except Exception: pass
{'state':state,'elements':facts[:80],'count':len(facts)}

